// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.19;

import '../interfaces/IZKFirmaDigital.sol';
import '../interfaces/IZKFirmaDigitalVote.sol';

// Minimal verifier interface for passport proofs (top-level)
interface IProofVerifier {
    function verifyProof(
        bytes32 registrationRoot,
        uint256 currentDate,
        bytes calldata userPayload,
        uint256[2] calldata a,
        uint256[2][2] calldata b,
        uint256[2] calldata c
    ) external view returns (bool);
}

contract ZKFirmaDigitalVote is IZKFirmaDigitalVote {
    string public votingQuestion;
    address public ZKFirmaDigitalVerifierAddr;

    // Optional vote params used by frontend
    uint256 public identityCreationTimestampUpperBound;
    uint256 public birthDateLowerbound;
    uint256 public expirationDateLowerBound;
    uint256 public identityCounterUpperBound;
    uint64 public voteScope;

    // List of proposals
    Proposal[] public proposals;

    // Mapping to track if a userNullifier has already voted
    mapping(uint256 => bool) public hasVoted;

    // Proof points structure compatible with frontend ABI
    struct ProofPoints {
        uint256[2] a;
        uint256[2][2] b;
        uint256[2] c;
    }


    // Constructor to initialize proposals
    constructor(
        string memory _votingQuestion,
        string[] memory proposalDescriptions,
        address _verifierAddr
    ) {
        ZKFirmaDigitalVerifierAddr = _verifierAddr;
        votingQuestion = _votingQuestion;
        for (uint256 i = 0; i < proposalDescriptions.length; i++) {
            proposals.push(Proposal(proposalDescriptions[i], 0));
        }
    }

    /// @dev Return vote parameters expected by frontend `voteParams()`
    /// Matches ABI: (string,uint256,uint256,uint256,uint256,uint64)
    function voteParams()
        public
        view
        returns (
            string memory,
            uint256,
            uint256,
            uint256,
            uint256,
            uint64
        )
    {
        return (
            votingQuestion,
            identityCreationTimestampUpperBound,
            birthDateLowerbound,
            expirationDateLowerBound,
            identityCounterUpperBound,
            voteScope
        );
    }

    /// @dev Execute a vote coming from a passport (ZK passport) flow.
    /// This is a minimal, frontend-compatible implementation that decodes
    /// the `userPayload` and registers the vote. It does NOT verify ZK proofs
    /// — integrate a verifier call here if available.
    function execute(
        bytes32 /* registrationRoot */,
        uint256 /* currentDate */,
        bytes calldata userPayload,
        ProofPoints calldata zkPoints_
    ) external {
        // Verify the zk proof on-chain via the configured verifier contract
        bool verified = IProofVerifier(ZKFirmaDigitalVerifierAddr).verifyProof(
            bytes32(0), // registrationRoot not used here (frontend passes it), verifier may ignore
            0, // currentDate not forwarded here for simplicity
            userPayload,
            zkPoints_.a,
            zkPoints_.b,
            zkPoints_.c
        );

        require(verified, '[ZKFirmaDigitalVote]: Passport proof verification failed');

        // Decode userPayload encoded as (uint256 vote, uint256 nullifier, uint256 citizenship, uint256 identityCreationTimestamp)
        (uint256 voteIndex, uint256 nullifier, , ) = abi.decode(userPayload, (uint256, uint256, uint256, uint256));

        require(voteIndex < proposals.length, '[ZKFirmaDigitalVote]: Invalid proposal index');
        require(!hasVoted[nullifier], '[ZKFirmaDigitalVote]: User has already voted');

        proposals[voteIndex].voteCount++;
        hasVoted[nullifier] = true;

        emit Voted(msg.sender, voteIndex);
    }

    /// @dev Convert an address to uint256, used to check against signal.
    /// @param _addr: msg.sender address.
    /// @return Address msg.sender's address in uint256
    function addressToUint256(address _addr) private pure returns (uint256) {
        return uint256(uint160(_addr));
    }

    /// @dev Check if the timestamp is more recent than (current time - 3 hours)
    /// @param timestamp: msg.sender address.
    /// @return bool
    /// TODO: add an actual timestamp check
    function isLessThan3HoursAgo(uint timestamp) public view returns (bool) {
        return true;
    }

    /// @dev Register a vote in the contract.
    /// @param proposalIndex: Index of the proposal you want to vote for.
    /// @param nullifierSeed: Nullifier Seed used while generating the proof.
    /// @param nullifier: Nullifier for the user's ZK Firma Digital data.
    /// @param signal: signal used while generating the proof, should be equal to msg.sender.
    /// @param revealArray: Array of the values used to reveal data, if value is 1 data is revealed, not if 0.
    /// @param groth16Proof: SNARK Groth16 proof.
    function voteForProposal(
        uint256 proposalIndex,
        uint nullifierSeed,
        uint nullifier,
        uint signal,
        uint[1] calldata revealArray, 
        uint[8] calldata groth16Proof
    ) public {
        require(
            proposalIndex < proposals.length,
            '[ZKFirmaDigitalVote]: Invalid proposal index'
        );
        require(
            addressToUint256(msg.sender) == signal,
            '[ZKFirmaDigitalVote]: Wrong user signal sent.'
        );
        require(
            isLessThan3HoursAgo(0),
            '[ZKFirmaDigitalVote]: Proof must be generated with ZK Firma Digital data signed less than 3 hours ago.'
        );
        require(
            IZKFirmaDigital(ZKFirmaDigitalVerifierAddr).verifyZKFirmaDigitalProof(
                nullifierSeed, // nullifier seed
                nullifier,
                signal,
                revealArray,
                groth16Proof
            ),
            '[ZKFirmaDigitalVote]: The proof sent is not valid.'
        );
        // Check that user hasn't already voted
        require(
            !hasVoted[nullifier],
            '[ZKFirmaDigitalVote]: User has already voted'
        );

        proposals[proposalIndex].voteCount++;
        hasVoted[nullifier] = true;

        emit Voted(msg.sender, proposalIndex);
    }

    // Function to get the total number of proposals
    function getProposalCount() public view returns (uint256) {
        return proposals.length;
    }

    // Function to get proposal information by index
    function getProposal(
        uint256 proposalIndex
    ) public view returns (string memory, uint256) {
        require(
            proposalIndex < proposals.length,
            '[ZKFirmaDigitalVote]: Invalid proposal index'
        );

        Proposal memory proposal = proposals[proposalIndex];
        return (proposal.description, proposal.voteCount);
    }

    // Function to get the total number of votes across all proposals
    function getTotalVotes() public view returns (uint256) {
        uint256 totalVotes = 0;
        uint256 proposalLength = proposals.length;
        for (uint256 i = 0; i < proposalLength; i++) {
            totalVotes += proposals[i].voteCount;
        }
        return totalVotes;
    }

    // Function to check if a user has already voted
    function checkVoted(uint256 _nullifier) public view returns (bool) {
        return hasVoted[_nullifier];
    }
}

